codeExample.code:
#include <stdio.h>
#include <string.h>

int main() {
    /* Declare and initialize strings */
    char firstName[20] = "Ravi";
    char lastName[20]  = "Kumar";
    char fullName[41];

    /* Copy firstName into fullName */
    strcpy(fullName, firstName);

    /* Append a space */
    strcat(fullName, " ");

    /* Append lastName */
    strcat(fullName, lastName);

    /* Print results */
    printf("First Name : %s\n", firstName);
    printf("Last  Name : %s\n", lastName);
    printf("Full  Name : %s\n", fullName);

    /* Show string length */
    printf("Length of full name: %lu\n",
           (unsigned long)strlen(fullName));

    /* Compare two strings */
    if (strcmp(firstName, "Ravi") == 0) {
        printf("First name matches Ravi\n");
    } else {
        printf("Names do not match\n");
    }

    return 0;
}

