questions.solution:
#include <stdio.h>
#include <string.h>

int main() {
    char sentence[51];

    printf("Enter a sentence: ");
    fgets(sentence, sizeof(sentence), stdin);

    printf("You entered: %s", sentence);
    printf("Length: %d\n", (int)strlen(sentence));

    return 0;
}
